/** Highest number the project has ever issued: live rows or the retired mark. */
function highestNumber(orgId: OrgId, projectId: ProjectId): number {
  const db = getDb();
  const row = db
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  const mark = db
    .select({ value: projectIssueNumbers.highest })
    .from(projectIssueNumbers)
    .where(eq(projectIssueNumbers.projectId, projectId))
    .get();
  return Math.max(row?.value ?? 0, mark?.value ?? 0);
}

/** Raises the project's retired-number mark to at least `number`. */
function raiseMark(orgId: OrgId, projectId: ProjectId, number: number): void {
  getDb()
    .insert(projectIssueNumbers)
    .values({ projectId, orgId, highest: number })
    .onConflictDoUpdate({
      target: projectIssueNumbers.projectId,
      set: { highest: sql`max(${projectIssueNumbers.highest}, ${number})` },
    })
    .run();
}

/**
 * Re-files an issue under another project with that project's next number,
 * retiring the old one in the source project. Atomic.
 */
export async function moveIssueToProject(
  orgId: OrgId,
  issueId: IssueId,
  toProjectId: ProjectId,
): Promise<Issue> {
  const row = getDb().transaction(() => {
    const current = getDb()
      .select()
      .from(issues)
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .get();
    if (!current) throw new Error(`Issue ${issueId} not found`);

    const toNumber = highestNumber(orgId, toProjectId) + 1;
    raiseMark(orgId, current.projectId as ProjectId, current.number);
    raiseMark(orgId, toProjectId, toNumber);

    return getDb()
      .update(issues)
      .set({
        projectId: toProjectId,
        number: toNumber,
        updatedAt: toIsoTimestamp(new Date()),
      })
      .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
      .returning()
      .get();
  });

  const labels = await listLabelsForIssues(orgId, [issueId]);
  return toIssue(row, (labels[issueId] ?? []).map((label) => label.id));
}
